ent = latestProps.current;\n      setBusyFormat(format);\n      setFailedFormat(null);\n      try {\n        const file = await buildExportFile(format, current, containerRef.current);\n        await deliverFile(file.blob, file.fileName, current.utilities);\n        return true;\n      } catch (error) {\n        console.error(`[ExportableData] $' + CAST(N'' AS NVARCHAR(MAX)) + N'{format} export of \"$' + CAST(N'' AS NVARCHAR(MAX)) + N'{current.exportID}\" failed:`, error);\n        if (mountedRef.current) setFailedFormat(format);\n        return false;\n      } finally {\n        if (mountedRef.current) setBusyFormat(null);\n      }\n    }, [latestProps, containerRef]);\n\n    return { busyFormat, failedFormat, runExport };\n  }\n\n  /** Registers with the host''s export registry when the host provides one (later MJ releases). */\n  function useHostRegistration(latestProps, containerRef, exportID) {\n    React.useEffect(() => {\n      const hostExport = latestProps.current.utilities && latestProps.current.utilities.export;\n      if (!hostExport || typeof hostExport.RegisterElement !== ''function'') return undefined;\n      try {\n        const unregister = hostExport.RegisterElement({\n          ExportID: exportID,\n          GetLabel: () => latestProps.current.label,\n          GetKind: () => latestProps.current.kind,\n          GetRows: async () => (await resolveExportData(latestProps.current.rows, latestProps.current.getRows)).rows,\n          GetColumns: () => resolveColumns(latestProps.current.columns, latestProps.current.rows || [], exportID),\n          GetImage: () => captureImage(latestProps.current.getImage, containerRef.current),\n          Element: containerRef.current\n        });\n        return typeof unregister === ''function'' ? unregister : undefined;\n      } catch (error) {\n        console.error(`[ExportableData] Registering \"$' + CAST(N'' AS NVARCHAR(MAX)) + N'{exportID}\" with the host failed:`, error);\n        return undefined;\n      }\n    }, [exportID, latestProps, containerRef]);\n  }\n\n  /**\n   * ''toolbar'': flush with the element''s top-right corner at antd''s 32px control height, always shown, so it\n   * lines up with a toolbar row (a grid''s search box) that leaves room for it.\n   * ''overlay'': a smaller button over the element''s top-right corner, shown on hover or keyboard focus (and\n   * always on touch screens), as BI tools show a visual''s header; no space is reserved for it.\n   */\n  const PLACEMENTS = {\n    toolbar: { top: 0, right: 0, size: 32 },\n    overlay: { top: 6, right: 6, size: 26 }\n  };\n\n  function buttonStyle(colors, size, visible) {\n    return {\n      display: ''inline-flex'', alignItems: ''center'', justifyContent: ''center'',\n      width: size, height: size, padding: 0, cursor: ''pointer'', boxSizing: ''border-box'',\n      border: `1px solid $' + CAST(N'' AS NVARCHAR(MAX)) + N'{colors.border || ''#d9d9d9''}`, borderRadius: 6,\n      background: colors.surface || colors.background || ''#ffffff'',\n      color: colors.textSecondary || ''#555555'',\n      opacity: visible ? 1 : 0, transition: ''opacity 120ms ease''\n    };\n  }\n\n  /** The plain menu used when antd is not loaded. */\n  function fallbackMenuStyle(colors) {\n    return {\n      position: ''absolute'', top: 30, right: 0, minWidth: 140, padding: 4, zIndex: 11,\n      background: colors.surface || ''#ffffff'', border: `1px solid $' + CAST(N'' AS NVARCHAR(MAX)) + N'{colors.border || ''rgba(0,0,0,0.12)''}`,\n      borderRadius: 6, boxShadow: ''0 4px 12px rgba(0,0,0,0.12)''\n    };\n  }\n\n  function fallbackItemStyle(colors, item) {\n    return {\n      display: ''block'', width: ''100%'', textAlign: ''left'', padding: ''6px 10px'', border: ''none'', background: ''transparent'',\n      color: item.danger ? (colors.error || ''#c0392b'') : (colors.text || ''#222222''), cursor: item.disabled ? ''default'' : ''pointer''\n    };\n  }\n\n  // ---- Component ----\n  const { Dropdown } = unwrapLibraryComponents(typeof antd !== ''undefined'' ? antd : {}, ''Dropdown'');\n  const containerRef = React.useRef(null);\n  const latestProps = React.useRef(null);\n  latestProps.current = { exportID, label, kind, rows, getRows, columns, getImage, utilities };\n\n  const [open, setOpen] = React.useState(false);\n  const [hovered, setHovered] = React.useState(false);\n  const [focused, setFocused] = React.useState(false);\n  const touchOnly = React.useMemo(isTouchOnly, []);\n  const position = PLACEMENTS[placement] || PLACEMENTS.overlay;\n  const { busyFormat, failedFormat, runExport } = useExportRunner(latestProps, containerRef);\n  useHostRegistration(latestProps, containerRef, exportID);\n\n  const items = menuItemsFor(kind, busyFormat, failedFormat);\n  const handleSelect = async (key) => {\n    if (key === ''error'') return;\n    const succeeded = await runExport(key);\n    if (succeeded) setOpen(false);\n  };\n  const colors = (styles && styles.colors) || {};\n  const accessibleName = `Export $' + CAST(N'' AS NVARCHAR(MAX)) + N'{label || ''data''}`;\n  // antd''s Dropdown attaches its ref and handlers to this element, so it stays a plain <button>.\n  const button = (\n    <button\n      type=\"button\"\n      aria-label={accessibleName}\n      aria-haspopup=\"menu\"\n      aria-expanded={open}\n      title={accessibleName}\n      onClick={Dropdown ? undefined : () => setOpen(!open)}\n      onKeyDown={event => { if (event.key === ''Escape'') setOpen(false); }}\n      style={buttonStyle(colors, position.size, placement === ''toolbar'' || open || hovered || focused || touchOnly)}\n    >\n      <svg width={position.size > 28 ? 16 : 14} height={position.size > 28 ? 16 : 14} viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.6\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">\n        <path d=\"M8 2v8M4.5 6.5 8 10l3.5-3.5M2.5 13.5h11\" />\n      </svg>\n    </button>\n  );\n\n  return (\n    <div\n      ref={containerRef}\n      data-export-id={exportID}\n      style={{ minWidth: 0, ...(style || {}), position: ''relative'' }}\n      onMouseEnter={() => setHovered(true)}\n      onMouseLeave={() => setHovered(false)}\n      onFocus={() => setFocused(true)}\n      onBlur={() => setFocused(false)}\n    >\n      {children}\n      <div data-export-control=\"true\" style={{ position: ''absolute'', top: position.top, right: position.right, zIndex: 10 }}>\n        {Dropdown ? (\n          <Dropdown\n            trigger={[''click'']}\n            placement=\"bottomRight\"\n            open={open}\n            onOpenChange={setOpen}\n            menu={{ items, onClick: ({ key }) => handleSelect(key) }}\n          >\n            {button}\n          </Dropdown>\n        ) : (\n          <>\n            {button}\n            {open && (\n              <div role=\"menu\" style={fallbackMenuStyle(colors)}>\n                {items.map(item => (\n                  <button key={item.key} type=\"button\" role=\"menuitem\" disabled={item.disabled} onClick={() => handleSelect(item.key)} style={fallbackItemStyle(colors, item)}>\n                    {item.label}\n                  </button>\n                ))}\n              </div>\n            )}\n          </>\n        )}\n      </div>\n    </div>\n  );\n}\n","exampleUsage":"// Custom Chart.js chart: wrap the sized container, not the bare <canvas>\nconst { ExportableData } = components;\n\nconst chartRows = months.map((month, i) => ({\n  Month: month,\n  Revenue: revenue[i],\n  Target: target[i],\n  Attainment: revenue[i] / target[i]   // fraction, not ''87%''\n}));\n\n<ExportableData\n  exportID=\"revenue-by-month\"\n  label=\"Revenue by Month\"\n  kind=\"chart\"\n  rows={chartRows}\n  columns={[\n    { field: ''Month'', label: ''Month'', type: ''string'' },\n    { field: ''Revenue'', label: ''Revenue'', type: ''currency'' },\n    { field: ''Target'', label: ''Target'', type: ''currency'' },\n    { field: ''Attainment'', label: ''Attainment'', type: ''percent'' }\n  ]}\n>\n  <div style={{ height: 320 }}>\n    <canvas ref={canvasRef} />\n  </div>\n</ExportableData>\n\n// Custom table: export every row that passes the user''s filter, in the current sort, not just the visible page\n<ExportableData\n  exportID=\"overdue-invoices\"\n  label=\"Overdue Invoices\"\n  kind=\"table\"\n  rows={sortedFilteredInvoices}\n  columns={[\n    { field: ''InvoiceNumber'', label: ''Invoice'', type: ''string'' },\n    { field: ''Customer'', label: ''Customer'', type: ''string'' },\n    { field: ''DueDate'', label: ''Due'', type: ''date'' },\n    { field: ''Balance'', label: ''Balance'', type: ''currency'' }\n  ]}\n>\n  <table>{/* ... */}</table>\n</ExportableData>\n\n// Not a dataset: leave it unwrapped and say why\n{/* export-opt-out: single member detail panel */}\n<MemberDetailPanel member={selected} />"}'
SET
  @FunctionalRequirements_8cb035cd8380 = N'## Purpose
Give every table and chart in an interactive component the same export affordance, the same formats and the same file quality, whatever code the LLM wrote around it.

## Affordance
- One icon button in the element''s top-right corner, over the element (no layout change to the child).
- Subtle at rest, stronger on hover and keyboard focus, always visible on touch devices.
- Opens a menu: **CSV**, **Excel**, and **PNG** (charts only), in that order.
- Keyboard accessible: the button is focusable, Enter/Space opens the menu, arrow keys move, Escape closes. The button''s accessible name is "Export <label>".
- While a file is being prepared (async `getRows`, image capture) the menu item shows a spinner; a failure shows a short message and logs the error. It never throws into the host component.

## Data
- Exports `rows` (or the result of `getRows()`) with `columns`, in column order. `getRows` may return `{ rows, note }`; the note becomes the file''s last row, for a caller whose rows are partial.
- A table exports every row that passes the user''s filters, in the current sort, across all pages.
- A chart exports what it draws, in wide rows.
- Empty rows: the menu still opens; CSV and Excel produce a header-only file.

## Formats
| Format | Behaviour |
|---|---|
| CSV | UTF-8 with BOM, RFC 4180 quoting, CRLF line endings, header row of column labels. Dates as ISO `YYYY-MM-DD` (or ISO date-time when the value has a time). Cells starting with `=`, `+`, `-` or `@` are prefixed with `''` so spreadsheets do not run them as formulas. |
| Excel | One `.xlsx` sheet named after the label (31-character limit). Typed cells: number, currency (`$#,##0.00`), percent (`0.0%`), date (`yyyy-mm-dd`, or with time), boolean. A filter on the header row and column widths fitted to content. (The community build of SheetJS writes no cell styles, so the header is not bold or frozen.) |
| PNG | Charts only. Native export when the chart library offers one (Chart.js at 3× pixel ratio; ApexCharts at scale 3), otherwise an html2canvas capture of the wrapper''s subtree at 2×. Drawn on the background the element is shown on, so a dark theme''s labels stay readable. |

- Filename: `<label>_<YYYY-MM-DD>.<ext>`, with characters outside letters, digits, space, `-` and `_` replaced by `_`.
- Excel''s row limit (1,048,576) is enforced: larger exports are cut off, with a note row at the end.

## Integration
- Registry components (`DataGrid`, `EntityDataGrid`, `SimpleChart`) render it internally; generated code never wraps them.
- When the host provides the export runtime context (MJ host releases after this component), the element registers with it so the host can list and drive element exports and the root PDF. Without that context it works on its own.

## Out of scope
- Save as List (later, depends on MJ List write paths).
- Raw underlying records behind a summarized chart.
- Whole-component PDF (host-owned).
'
SET
  @TechnicalDesign_8cb035cd8380 = N'## Structure
```
<div data-export-id={exportID} style={{ position: ''relative'', ...style }}>
  {children}
  <ExportMenu />   // absolutely positioned top-right, z-index above the child
</div>
```
- The div is the only element added to the layout. A flex or grid item that is wrapped keeps its layout by moving its layout styles to `style`.
- The menu is an antd `Dropdown` (renders in a portal, so a parent with `overflow: hidden` does not clip it). The trigger is a plain `<button>` so it works without antd styles loaded.
- Nothing in the child is cloned or given extra props; the wrapper finds chart instances by searching its own subtree.

## Data flow
1. On a menu click, resolve rows: `await getRows()` when given, else `rows`, else `[]`. `getRows` may return `{ rows, note }` instead of an array; the note is written as the file''s last row (CSV and Excel). The host registration''s `GetRows` returns the rows only.
2. Resolve columns: `columns`, else the keys of the first row as `string` columns (logs a `console.warn` with the `exportID`).
3. Normalize each cell by column type (shared by CSV and Excel):
   - `number` / `currency` / `percent`: `Number(value)` when finite, else empty.
   - `date`: `Date` or parseable ISO string → `Date`; anything else is written as text.
   - `boolean`: `true`/`false`.
   - `string`: `String(value)`; `null`/`undefined` → empty.
4. Write the file and download it through a temporary object URL and anchor, revoked right after.

The download goes through one internal `deliverFile(blob, fileName, utilities)` function. When the host provides `utilities.export.DownloadFile(blob, fileName)` (MJ host releases after this component; the name is provisional until MJ defines the service), it is used instead of the browser download.

## Writers
- **CSV**: hand-written (no library). BOM `﻿`, fields quoted when they contain `"`, `,`, CR or LF, quotes doubled, formula-prefix guard on text cells.
- **Excel**: the sheet is built cell by cell with typed cells (`t: ''n'' | ''b'' | ''s''` and `z` number formats), `!cols` widths and an `!autofilter` on the header row, then `XLSX.write(..., { type: ''array'', bookType: ''xlsx'' })`. Dates are written as Excel serial numbers computed from their calendar parts, so no time zone shifts them; a bare `YYYY-MM-DD` string stays on its day.

## PNG
In order:
1. `getImage()` when given.
2. A Chart.js chart in the subtree: `Chart.getChart(canvas)`. Temporarily set `devicePixelRatio: 3`, `animation: false`, resize, `toBase64Image(''image/png'')`, then restore options and resize.
3. An ApexCharts chart in the subtree (`.apexcharts-canvas`): find the instance through `ApexCharts.getChartByID` on the element''s id, then `dataURI({ scale: 3 })`.
4. Fallback: `html2canvas(wrapperDiv, { scale: 2, backgroundColor: <background>, ignoreElements: the export button })`.

The image from steps 1–3 is drawn onto a canvas filled with `<background>`: the nearest opaque `background-color` from the wrapper up (translucent ones blended over it, white when there is none), resolved through a 1×1 canvas so any CSS colour syntax works. A dark theme''s light chart text would vanish on white. An opaque image is unchanged.

## Runtime registration
When the host provides `utilities.export.RegisterElement` (MJ host releases after this component; provisional name), register on mount and call the returned function on unmount:
`{ ExportID, GetLabel, GetKind, GetRows, GetColumns, GetImage, Element }`, with stable callbacks that read the latest props through a ref (not data snapshots). Feature-detected; an absent service is not an error.

The export button sits in a `data-export-control="true"` container, which the PNG capture ignores and a host print mode can hide.

## Error handling
Every export path is wrapped in try/catch: the error is logged with the `exportID` and format, and the menu shows "Export failed". No error reaches the host component or its error boundary.

## Libraries
- `antd` 5.12.0: menu.
- `xlsx` 0.18.5: Excel writer.
- `html2canvas` 1.4.1: PNG fallback.
'
